// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }
    function testFuzz_property(address expectedCollateral) public {
        vm.assume(expectedCollateral != address(0));
        bytes memory args = abi.encodePacked(
            address(0),
            expectedCollateral,
            address(0),
            address(0)
        );
        address implementation = address(new Cooler());

        address _collateral = address(uint160(uint256(keccak256(abi.encodePacked(expectedCollateral)))));
        address _factory = address(uint160(uint256(keccak256(abi.encodePacked(expectedCollateral, "factory")))));
        vm.assume(_collateral != _factory);

        bytes memory immArgs = abi.encodePacked(
            address(0x1),
            _collateral,
            address(0),
            _factory
        );
        uint16 immLength = uint16(immArgs.length);
        bytes4 selector = bytes4(keccak256("collateral()"));
        bytes memory calldata_ = abi.encodePacked(selector, immArgs, immLength);

        (bool success, bytes memory ret) = address(c).call(calldata_);
        address returnedCollateral = abi.decode(ret, (address));
        assertTrue(success && returnedCollateral == _collateral);
    }
}
